CREATE FUNCTION f_while(n INT) RETURNS INT AS
$$
DECLARE
  i INT DEFAULT 0;
  s INT DEFAULT 0;
BEGIN
  WHILE (i < n) DO
    i := i + 1;
    s := s + i;
  END WHILE;
  RETURN s;
END
$$

CREATE PROCEDURE p_caller() RETURNS VARCHAR LANGUAGE SQL AS
$$
DECLARE
  x INT DEFAULT 5;
  y INT;
BEGIN
  y := f_own_x();
  RETURN x || '/' || y;
END
$$

